package contracts

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"reflect"
	"testing"

	"github.com/accessdurin/cli/internal/jsjson"
	"github.com/accessdurin/cli/internal/zod"
)

// fixtures.json is generated by testdata/gen.mjs from the TypeScript contracts and the real
// zod 4.1.13, so these tests pin Node's exact outcomes.
type fixtures struct {
	Schemas []struct {
		Schema string `json:"schema"`
		Input  string `json:"input"`
		OK     bool   `json:"ok"`
		Output string `json:"output"`
		Threw  string `json:"threw"`
		Custom []struct {
			Message string `json:"message"`
			Path    []any  `json:"path"`
		} `json:"custom"`
	} `json:"schemas"`
	Functions []struct {
		Fn     string            `json:"fn"`
		Args   []json.RawMessage `json:"args"`
		Result any               `json:"result"`
		Threw  string            `json:"threw"`
	} `json:"functions"`
}

func loadFixtures(t *testing.T) fixtures {
	t.Helper()
	data, err := os.ReadFile("testdata/fixtures.json")
	if err != nil {
		t.Fatal(err)
	}
	var f fixtures
	if err := json.Unmarshal(data, &f); err != nil {
		t.Fatal(err)
	}
	return f
}

var schemas = map[string]zod.Schema{
	"cliProfileSchema":            CliProfileSchema,
	"cliProfileScopeSchema":       CliProfileScopeSchema,
	"cliToolCallSchema":           CliToolCallSchema,
	"cliMcpNegotiationSchema":     CliMcpNegotiationSchema,
	"mcpToolsPageSchema":          McpToolsPageSchema,
	"mcpToolsListSchema":          McpToolsListSchema,
	"mcpToolResultSchema":         McpToolResultSchema,
	"mcpEndpointSchema":           McpEndpointSchema,
	"cliAuthConfigSchema":         CliAuthConfigSchema,
	"deviceChallengeSchema":       DeviceChallengeSchema,
	"deviceSessionSchema":         DeviceSessionSchema,
	"authorizationCallbackSchema": AuthorizationCallbackSchema,
	"onboardingStatusSchema":      OnboardingStatusSchema,
	"onboardingAnswerSchema":      OnboardingAnswerSchema,
	"sessionSchema":               SessionSchema,
	"organizationCreateSchema":    OrganizationCreateSchema,
	"personalBootstrapSchema":     PersonalBootstrapSchema,
}

func TestSchemasMatchZod(t *testing.T) {
	for i, c := range loadFixtures(t).Schemas {
		schema := schemas[c.Schema]
		input, err := jsjson.ParseString(c.Input)
		if err != nil {
			t.Fatal(err)
		}
		var out jsjson.Value
		var issues *zod.Error
		var threw error
		func() {
			defer catch(&threw)
			out, issues = zod.SafeParse(schema, input)
		}()
		name := fmt.Sprintf("#%d %s %.120s", i, c.Schema, c.Input)
		if c.Threw != "" {
			var te *TypeError
			if !errors.As(threw, &te) {
				t.Errorf("%s: want a thrown %s, got %v", name, c.Threw, issues)
			}
			continue
		}
		if threw != nil {
			t.Errorf("%s: threw %v", name, threw)
			continue
		}
		if (issues == nil) != c.OK {
			t.Errorf("%s: ok=%v, want %v (issues %+v)", name, issues == nil, c.OK, issues)
			continue
		}
		if c.OK {
			if got := jsjson.Stringify(out); got != c.Output {
				t.Errorf("%s:\n got %s\nwant %s", name, got, c.Output)
			}
			continue
		}
		var custom []string
		for _, is := range issues.Issues {
			if is.Code == "custom" {
				custom = append(custom, fmt.Sprintf("%s %v", is.Message, is.Path))
			}
		}
		var want []string
		for _, is := range c.Custom {
			want = append(want, fmt.Sprintf("%s %v", is.Message, is.Path))
		}
		if !reflect.DeepEqual(custom, want) {
			t.Errorf("%s: custom issues\n got %q\nwant %q", name, custom, want)
		}
	}
}

func TestHostFunctionsMatchNode(t *testing.T) {
	type scope struct {
		AppOrigin     string `json:"appOrigin"`
		Development   bool   `json:"development"`
		AccountIssuer string `json:"accountIssuer"`
	}
	type allowlist struct {
		Hosts       []string `json:"hosts"`
		Development bool     `json:"development"`
	}
	str := func(raw json.RawMessage) string { var s string; _ = json.Unmarshal(raw, &s); return s }
	hostScope := func(raw json.RawMessage) CliHostScope {
		var s scope
		_ = json.Unmarshal(raw, &s)
		return CliHostScope(s)
	}
	for i, c := range loadFixtures(t).Functions {
		var got any
		var err error
		switch c.Fn {
		case "safeCliUrl":
			var dev bool
			_ = json.Unmarshal(c.Args[1], &dev)
			got = SafeCliURL(str(c.Args[0]), dev)
		case "loopbackCliHost":
			got = LoopbackCliHost(str(c.Args[0]))
		case "untrustedCliHost":
			var problem string
			problem, err = UntrustedCliHost(CliHostRole(str(c.Args[0])), str(c.Args[1]), hostScope(c.Args[2]))
			got = problem
			if problem == "" {
				got = nil
			}
		case "canonicalIssuer":
			got, err = CanonicalIssuer(CliHostRole(str(c.Args[0])), str(c.Args[1]), hostScope(c.Args[2]))
		case "comparableIssuer":
			got, err = ComparableIssuer(CliHostRole(str(c.Args[0])), str(c.Args[1]), hostScope(c.Args[2]))
		case "roundTripCliUrl":
			got = RoundTripCliURL(str(c.Args[0]))
		case "deploymentHostAllowlist":
			var list CliHostAllowlist
			list, err = DeploymentHostAllowlist(hostScope(c.Args[0]))
			hosts := []any{}
			for _, h := range list.Hosts {
				hosts = append(hosts, h)
			}
			got = map[string]any{"hosts": hosts, "development": list.Development}
		case "unlistedCliHost":
			var a allowlist
			_ = json.Unmarshal(c.Args[1], &a)
			var problem string
			problem, err = UnlistedCliHost(str(c.Args[0]), CliHostAllowlist(a))
			got = problem
			if problem == "" {
				got = nil
			}
		default:
			t.Fatalf("unknown function %s", c.Fn)
		}
		name := fmt.Sprintf("#%d %s%s", i, c.Fn, c.Args)
		if c.Threw != "" {
			if err == nil {
				t.Errorf("%s: want a throw, got %v", name, got)
			}
			continue
		}
		if err != nil || !reflect.DeepEqual(got, c.Result) {
			t.Errorf("%s:\n got %#v (%v)\nwant %#v", name, got, err, c.Result)
		}
	}
}

func TestCreateProfileHashesTheScopeInSchemaOrder(t *testing.T) {
	scope := CliProfileScope{
		AppOrigin: "https://app.example.test", AccountIssuer: "https://app.example.test/", AccountClientID: "c",
		PrincipalID: "u", WorkosOrganizationID: "w", OrganizationID: "o", Environment: "production",
		Resource:  "https://app.example.test/mcp/u/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
		McpIssuer: "https://app.example.test/",
	}
	profile, err := CreateProfile(scope)
	if err != nil {
		t.Fatal(err)
	}
	// sha256 of JSON.stringify(scope), computed by Node.
	if profile.ID != "4ca1c8397ba3832b32dfce9ffd146e813f832aec4da8e77c09ca22240d1cc6e7" {
		t.Fatalf("id %s", profile.ID)
	}
	parsed, issues, err := SafeParseCliProfile(profile.JSON())
	if err != nil || issues != nil || parsed != profile {
		t.Fatalf("round trip: %+v %v %v", parsed, issues, err)
	}
	scope.Resource = "https://app.example.test/mcp/u/short"
	var zerr *zod.Error
	if _, err := CreateProfile(scope); !errors.As(err, &zerr) {
		t.Fatalf("invalid scope: %v", err)
	}
}
